"""Check the PTX frameworks' kernels with Volta: races and, against a spec, correctness.

    python3 external/ptx/verify.py                    # every framework's cases
    python3 external/ptx/verify.py vllm               # one framework (`FRAMEWORKS`)
    python3 external/ptx/verify.py vllm -k rms_norm   # the cases whose name contains it
    python3 external/ptx/verify.py --build            # compile the cases' units first

Each framework has a `<framework>/cases.py` registry. A case's kernel is found by its
`symbol` in the PTX `external/ptx/extraction/survey.py` compiled from its `unit` (`--build`
compiles the units the selected cases name); its launch file is written to
`<framework>/launch/<case>.launch.json` and run with `volta solve`. A case PASSes when the
verdict is the one it expects. `--table` (by default `output/ptx_table.md`) lists every
case's verdict, as `external/amd/table.py` does for the AMD libraries. The exit status is 1
if any case's verdict is not its expected one.
"""

import argparse
import importlib.util
import json
import re
import subprocess
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

PTX_ROOT = Path(__file__).resolve().parent
REPO_ROOT = PTX_ROOT.parent.parent
VOLTA = REPO_ROOT / "target" / "release" / "volta"
SURVEY_DIR = PTX_ROOT / "survey"
FRAMEWORKS = ("vllm",)
DEFAULT_TABLE = PTX_ROOT / "output" / "ptx_table.md"

ENTRY = re.compile(r"^\.visible \.entry (\S+?)\(", re.MULTILINE)


def load(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def ptx_of(framework: str, unit: str) -> Path:
    return SURVEY_DIR / framework / Path(unit).with_suffix(".ptx")


def kernel_of(ptx: Path, symbol: str | tuple) -> str:
    parts = (symbol,) if isinstance(symbol, str) else symbol
    names = [n for n in ENTRY.findall(ptx.read_text()) if all(p in n for p in parts)]
    if len(names) != 1:
        raise LookupError(f"{len(names)} kernels of {ptx.name} contain {symbol!r}: {names[:4]}")
    return names[0]


def param(arg) -> dict:
    kind = type(arg).__name__
    label = {"name": arg.name} if getattr(arg, "name", "") else {}
    if kind == "Ptr":
        return {"ptr": arg.array}
    if kind == "Int":
        return {**label, "int": arg.value}
    if kind == "Float":
        return {**label, "float": arg.value}
    raise TypeError(f"unknown argument {arg!r}")


def array(a) -> dict:
    placed = {"base": hex(a.base)} if getattr(a, "base", None) is not None else {}
    return {"name": a.name, "kind": a.kind, "dtype": a.dtype, "shape": list(a.shape), **placed}


def launch_file(framework: str, case, kernel: str) -> dict:
    launch = {
        "description": f"{framework} {case.source}: {case.description}. "
                       "Generated by external/ptx/verify.py.",
        "kernel": kernel,
        "grid": list(case.grid),
        "block": case.block,
        **({"cta": list(case.cta)} if any(case.cta) else {}),
        "arrays": [array(a) for a in case.arrays],
        "params": [param(a) for a in case.args],
    }
    if case.spec:
        launch["spec"] = f"../{case.spec}"
        launch["dims"] = case.dims
    return launch


VERDICT = re.compile(r"^VERDICT: (\w+)", re.MULTILINE)


def verdict_of(output: str, has_spec: bool) -> str:
    """The run's verdict: the spec's, else the graph checks'; ABORT if the run stopped."""
    if match := VERDICT.search(output):
        if has_spec:
            return match.group(1)
    elif has_spec and "graph verification" not in output:
        return "ERROR"
    if "error:" in output and "VERDICT" not in output:
        return "ABORT"
    if "every graph check passed" in output:
        return "VERIFIED"
    return "REJECTED"


def run_case(framework: str, case, timeout: int) -> dict:
    start = time.time()
    result = {"framework": framework, "case": case.name, "expected": case.check,
              "description": case.description}
    try:
        ptx = ptx_of(framework, case.unit)
        kernel = kernel_of(ptx, case.symbol)
        path = PTX_ROOT / framework / "launch" / f"{case.name}.launch.json"
        path.parent.mkdir(exist_ok=True)
        path.write_text(json.dumps(launch_file(framework, case, kernel), indent=2) + "\n")
        command = [str(VOLTA), "--no-log-file", "solve", str(ptx), "--config", str(path),
                   "--print-outputs", "0"]
        run = subprocess.run(command, capture_output=True, text=True, timeout=timeout)
        output = run.stdout + run.stderr
        result["verdict"] = verdict_of(output, case.spec is not None)
        result["detail"] = detail_of(output)
    except subprocess.TimeoutExpired:
        result["verdict"], result["detail"] = "UNKNOWN", f"no verdict within {timeout}s"
    except (LookupError, FileNotFoundError) as error:
        result["verdict"], result["detail"] = "ERROR", str(error)
    result["seconds"] = round(time.time() - start, 1)
    result["passed"] = result["verdict"] == case.check
    return result


def detail_of(output: str) -> str:
    """The first line explaining a verdict other than ACCEPT."""
    for line in output.splitlines():
        line = line.strip()
        if line.startswith(("error:", "equivalence:", "evidence:", "----------", "expected ")) \
                or "FAIL" in line or "panicked" in line:
            return " ".join(line.split())[:300]
    return ""


def build(framework: str, cases) -> None:
    survey = load(PTX_ROOT / "extraction" / "survey.py", "survey")
    suite = next(s for s in survey.SUITES if s.framework == framework)
    units = tuple(sorted({c.unit for c in cases}))
    survey.compile_all([suite], jobs=2, timeout=1500, only=units)


def write_table(path: Path, results: list[dict]) -> None:
    lines = ["# PTX framework kernels", "", "Generated by `external/ptx/verify.py`.", "",
             "| Framework | Case | Expected | Verdict | Result | Detail | Time |",
             "|---|---|---|---|---|---|---:|"]
    for r in results:
        outcome = "correct" if r["verdict"] in ("ACCEPT", "VERIFIED") else "bug"
        if not r["passed"]:
            outcome = "unexpected"
        detail = r["detail"].replace("|", "\\|")
        lines.append(f"| {r['framework']} | `{r['case']}` | {r['expected']} | {r['verdict']} | "
                     f"{outcome} | {detail} | {r['seconds']} s |")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines) + "\n")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("frameworks", nargs="*", help=f"some of {', '.join(FRAMEWORKS)}")
    parser.add_argument("-k", default="", help="run only the cases whose name contains this")
    parser.add_argument("--build", action="store_true", help="compile the cases' units first")
    parser.add_argument("--jobs", type=int, default=4)
    parser.add_argument("--timeout", type=int, default=600)
    parser.add_argument("--table", type=Path, default=DEFAULT_TABLE)
    args = parser.parse_args()
    if unknown := [f for f in args.frameworks if f not in FRAMEWORKS]:
        parser.error(f"unknown frameworks {unknown}")

    subprocess.run(["cargo", "build", "--release", "-q", "-p", "volta_cli"], cwd=REPO_ROOT, check=True)
    results = []
    for framework in args.frameworks or FRAMEWORKS:
        registry = load(PTX_ROOT / framework / "cases.py", f"{framework}_cases")
        cases = [c for c in registry.CASES if args.k in c.name]
        if args.build:
            build(framework, cases)
        with ThreadPoolExecutor(args.jobs) as pool:
            for r in pool.map(lambda c: run_case(framework, c, args.timeout), cases):
                status = "PASS" if r["passed"] else "FAIL"
                note = "" if r["verdict"] == r["expected"] else f" (expected {r['expected']})"
                print(f"{status} {framework}/{r['case']}: {r['verdict']}{note} {r['seconds']}s"
                      f"{'  ' + r['detail'] if r['detail'] else ''}", flush=True)
                results.append(r)
    write_table(args.table, results)
    print(f"\n{sum(r['passed'] for r in results)} of {len(results)} as expected; wrote {args.table}")
    return 0 if all(r["passed"] for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())
